32	namespace dec = ::sg::fused::sm90::dec;
33	using ::sg::fused::PersistentContext;
34	using ::sg::fused::sm90::DecoderTokenCtx;
35	using ::sg::fused::sm90::FusedOptState;
36	using ::sg::fused::sm90::OptId;
