39	// One persistent set of barrier/queue counters + the TC workspace, cached per
40	// device (the kernel zeroes the barrier per launch; the workspace is sized for
41	// the TC layout, NOT the scalar 223 MB partials). Re-created if a larger B
42	// requires a larger workspace.
43	struct TcScratch {
44	    torch::Tensor g_next;       // int [1]
45	    torch::Tensor g_arrived;    // int [1]
46	    torch::Tensor g_generation; // int [1]
47	    torch::Tensor workspace;    // float [dec_tc_workspace_floats(T,B,nCTA)]
48	    int n_ctas = 0;
49	    int64_t ws_floats = 0;
50	};
51	
52	// Effective nCTA the launcher will use (must match for workspace + ownership).
53	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
54	    int dev = params.get_device();
55	    int n_sms = 1;
56	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
57	    int n = n_sms;
58	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
59	    return n;
60	}
61	
62	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
63	    static TcScratch s;
64	    const int T = B * dec::kSeq;
65	    const int64_t need = ::sg::fused::sm90::dec_tc_workspace_floats(T, B, nCTA);
66	    if (!s.g_next.defined()) {
67	        auto opt_i = torch::dtype(torch::kInt32).device(params.device());
68	        s.g_next = torch::zeros({1}, opt_i);
69	        s.g_arrived = torch::zeros({1}, opt_i);
70	        s.g_generation = torch::zeros({1}, opt_i);
71	    }
72	    s.n_ctas = nCTA;
73	    if (s.ws_floats < need) {
74	        auto opt_f = torch::dtype(torch::kFloat32).device(params.device());
75	        s.workspace = torch::empty({need}, opt_f);
76	        s.ws_floats = need;
77	    }
78	    return s;
79	}
