137	// CALIBRATION HOOK (test_decoder_tc.py::test_tc_dw_gemm_exact_on_own_operands):
138	// slice the kernel's OWN stored bf16 acts dY_ff2[L1] [T,d] and X_gact[L1] [T,dff]
139	// from the workspace, returned as fp32 CPU tensors. The gate contracts them in
140	// fp32 ascending-t and compares to the kernel's ff2.weight grad slice — isolating
141	// the dW GEMM (incl. the ONLY Kin=dff multi-N-tile path, untested by the 13/13
142	// engine micro-gates) from the operand-chain bf16 divergence. A ~1e-6 match
143	// proves the dW GEMM is bit-exact on its own operands, calibrating the per-tensor
144	// bf16 tolerance as headroom over a GEMM-exact floor. Re-uses the cached
145	// workspace from the last tc_train_step (call AFTER it). Read-only; ships in the
146	// test TU only (never globbed into the .so).
147	static std::vector<torch::Tensor> tc_dump_ff2_operands(torch::Tensor params, int64_t B) {
148	    const int nCTA = tc_effective_nctas(params, 0);  // unused for offsets; acts layout is nCTA-independent
149	    (void)nCTA;
150	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
151	    const int T = (int)B * dec::kSeq;
152	    const int64_t d = dec::kD, dff = dec::kDff;
153	    auto acts_bf16 = sc.workspace.slice(0, 0, ::sg::fused::sm90::dec_tc_acts_floats(T, (int)B))
154	                         .view(torch::kBFloat16);
155	    // mirror dec_acts_bind: walk to dY_ff2[1] and X_gact[1].
156	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
157	    int64_t off = 0; int64_t off_Xgact1 = -1, off_dYff2_1 = -1;
158	    for (int li = 0; li < dec::kLayers; ++li) {
159	        off += Td;          // X_in
160	        off += Td;          // X_ctx
161	        off += Td;          // X_x1
162	        if (li == 1) off_Xgact1 = off;
163	        off += Tff;         // X_gact
164	        off += T3d;         // dY_qkv
165	        off += Td;          // dY_a
166	        off += Tff;         // dY_ff0
167	        if (li == 1) off_dYff2_1 = off;
168	        off += Td;          // dY_ff2
169	    }
170	    auto Xgact1 = acts_bf16.slice(0, off_Xgact1, off_Xgact1 + Tff).to(torch::kFloat32).to(torch::kCPU);
171	    auto dYff2_1 = acts_bf16.slice(0, off_dYff2_1, off_dYff2_1 + Td).to(torch::kFloat32).to(torch::kCPU);
172	    return {dYff2_1, Xgact1};  // [T*d], [T*dff]
173	}
