302	PYBIND11_MODULE(TORCH_EXTENSION_NAME, mm) {
303	    mm.def("tc_train_step", &tc_train_step,
304	           "Fork-B tensor-core decoder fwd+bwd+AdamW step (in place); returns (loss, reduced grad)",
305	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
306	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
307	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
308	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"),
309	           pybind11::arg("ncta_cap") = 0);
310	    mm.def("tc_dump_ff2_operands", &tc_dump_ff2_operands,
311	           "gate-only: dump the kernel's stored dY_ff2[L1], X_gact[L1] (fp32 CPU)");
312	#if SG_DEC_SCALAR_MEGAKERNEL
313	    mm.def("scalar_train_step", &scalar_train_step,
314	           "gate-only: SAME cell via the SCALAR launcher (back-to-back step-time mirror)",
315	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
316	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
317	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
318	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"));
319	#endif
320	    mm.attr("TILE_M") = (int)::sg::fused::sm90::dectc::kTileM;
