324	    mm.attr("DFF") = (int)::sg::fused::sm90::SG_DEC_DFF;
325	    mm.attr("LAYERS") = (int)::sg::fused::sm90::SG_DEC_LAYERS;
326	    mm.attr("SEQ") = (int)::sg::fused::sm90::SG_DEC_SEQ;
327	    mm.attr("VOCAB") = (int)::sg::fused::sm90::SG_DEC_VOCAB;
328	#ifdef SG_DEC_PROFILE
329	    mm.def("tc_profile_read", &tc_profile_read,
330	           "diagnostic-only: per-phase clock64 maxima "
331	           "[P1fwd,P1bwd,B1wait,P2dW,P2asm,P3opt,B2wait,B0wait] (cycles), resets after read");
332	    mm.attr("HAS_PROFILE") = true;
333	#if SG_DEC_PROFILE_FWD_FINE
334	    mm.def("tc_profile_read_fwd_fine", &tc_profile_read_fwd_fine,
335	           "diagnostic-only: FINE fwd/dX sub-phase clock64 maxima, flat "
336	           "[phase*FWD_FINE_SUB + sub]; phase 0=fwd ring, 1=dX ring; "
337	           "sub {0 ISSUE,1 WAIT(drain),2 WGMMA,3 EPI,4 BARRIER} (cycles), resets after read");
338	    mm.attr("HAS_FWD_FINE") = true;
339	    mm.attr("FWD_FINE_SUB") = (int)::sg::fused::sm90::dectc::kDecFwdFineSub;       // 5
340	    mm.attr("FWD_FINE_PHASES") = (int)::sg::fused::sm90::dectc::kDecFwdFinePhases; // 2
341	#else
342	    mm.attr("HAS_FWD_FINE") = false;
343	#endif
344	#else
345	    mm.attr("HAS_PROFILE") = false;
346	    mm.attr("HAS_FWD_FINE") = false;
347	#endif
348	    // Expose the fwd/dX deeper-ring knobs so the bench/main-loop can report them.
349	    mm.attr("FWD_PIPE") = (int)::sg::fused::sm90::dectc::kDecFwdPipe;
350	    mm.attr("FWD_STAGES") = (int)::sg::fused::sm90::dectc::kDecFwdStages;
